// This file is generated by AI.

// 护栏: 核对运行期拼出来的类名是否都有对应的 CSS (失败即退出 1)。
// 用法: node scripts/check-dynamic-classes.mjs
//
// 静态扫描看不出 `` `dialog-${size}` `` 或 `class="diag-sev-{severity}"` 会产出哪些具体类名,
// 清理死 CSS 时容易把整组规则删掉; 这里从**模板表达式**出发列出可能的类名, 再逐一对表。

import { readFileSync } from 'node:fs';
import { join, relative } from 'node:path';

import { editorRoot, walkFiles } from './walk.mjs';

const srcDir = join(editorRoot, 'src');
const css = readFileSync(join(srcDir, 'styles.css'), 'utf8');

const files = walkFiles(srcDir)
  .filter((file) => file.endsWith('.svelte'))
  .map((file) => ({ file: relative(srcDir, file).replace(/\\/g, '/'), text: readFileSync(file, 'utf8') }));

/** 已知的插值取值域: 从代码里读出来的"可能值"。 */
const DOMAINS = {
  // `dialog-${size}` 的取值
  'dialog-': ['small', 'form', 'medium', 'large'],
  // `diag-sev-{n}` 的取值 (Severity = 1|2|3|4)
  'diag-sev-': ['1', '2', '3', '4'],
  // `inline-diff-zone-${row.kind === '+' ? 'add' : 'del'}`
  'inline-diff-zone-': ['add', 'del'],
  // GSOV 服务状态: .voice-status-dot.ready 这类修饰类 (注意是复合选择器, 不是前缀)
  'voice-status-dot-': ['ready', 'starting', 'stopping', 'error'],
  // 任务状态的点色: `voice-dot-{status}`
  'voice-dot-': ['pending', 'running', 'done', 'failed', 'canceled'],
  // `task.status` 相关
  'voice-task-': [],
};

const problems = [];

/** 所有 `class="…"` 属性在文件里的字符区间, 用来判断某个模板字符串是否长在类名位置上。 */
function classRanges(text) {
  const ranges = [];
  for (const match of text.matchAll(/\bclass="([^"]*)"/g)) ranges.push([match.index, match.index + match[0].length]);
  return ranges;
}

for (const { file, text } of files) {
  const ranges = classRanges(text);
  const inClassAttribute = (index) => ranges.some(([start, end]) => index >= start && index <= end);

  /*
   * 模板字符串 `` `prefix-${...}` `` **只在 `class="…"` 属性里才算候选**。
   *
   * 否则任何"短横线 + 插值"的展示字符串 (菜单项的 `` key: `directory-${index}` ``、
   * 显示文本 `` `v${entry.version}` ``) 都会被当成类名, 护栏误报会让 `bun run lint` 变红。
   */
  for (const match of text.matchAll(/`([A-Za-z][A-Za-z0-9-]*)\$\{/g)) {
    if (!inClassAttribute(match.index)) continue;
    const prefix = match[1];
    const domain = DOMAINS[prefix];
    if (!domain) {
      problems.push({ file, prefix, kind: '未知取值域的模板字符串', detail: `\`${prefix}\${...}\`` });
      continue;
    }
    for (const value of domain) {
      const className = `${prefix}${value}`;
      if (!css.includes(`.${className}`)) {
        problems.push({ file, prefix, kind: 'CSS 里缺少这个类', detail: `.${className}` });
      }
    }
  }

  // Svelte 插值: class="... prefix-{expr} ..."
  for (const match of text.matchAll(/class="([^"]*)"/g)) {
    const attr = match[1];
    for (const inner of attr.matchAll(/([A-Za-z][A-Za-z0-9-]*-)\{/g)) {
      const prefix = inner[1];
      const domain = DOMAINS[prefix];
      if (!domain) {
        // 前缀本身在 CSS 里出现就认为整组已定义 (例如 `.voice-task-` 一族)
        if (!css.includes(`.${prefix}`)) {
          problems.push({ file, prefix, kind: '未登记的前缀且 CSS 里没有该前缀', detail: `${prefix}{…}` });
        }
        continue;
      }
      for (const value of domain) {
        const className = `${prefix}${value}`;
        if (!css.includes(`.${className}`)) {
          problems.push({ file, prefix, kind: 'CSS 里缺少这个类', detail: `.${className}` });
        }
      }
    }
  }
}

if (problems.length === 0) {
  console.log('运行期拼出的类名都有对应 CSS。');
} else {
  console.log(`发现 ${problems.length} 处可疑:`);
  for (const problem of problems) {
    console.log(`  ${problem.file}  [${problem.kind}] ${problem.detail}`);
  }
  process.exitCode = 1;
}
